{"term":"gigolo","lang":"nl","script":"latin","romanization":null,"category":"sex_work_pornography","subcategory":"gigolo","concept":"gigolo","is_novel_concept":false,"register":"loanword","crude":30,"technical":5,"recognition_pct_current":90,"recognition_pct_peak":90,"peak_year":null,"regional":null,"definition":"A male sex worker or paid male companion, especially one financially kept by an older, typically wealthy woman; French loanword used identically in Dutch and English.","english_term":"gigolo","english_translation_quality":"direct","notes":"French loanword absorbed into Dutch with identical meaning and connotations as in English; carries a slightly glamorizing or exotic framing compared to the more generic callboy."}
{"term":"pooier","lang":"nl","script":"latin","romanization":null,"category":"sex_work_pornography","subcategory":"pimp","concept":"pimp","is_novel_concept":false,"register":"slang_crude","crude":75,"technical":5,"recognition_pct_current":88,"recognition_pct_peak":90,"peak_year":null,"regional":null,"definition":"A pimp; a man who controls, manages, and profits from the sexual labor of sex workers, often through coercion or manipulation.","english_term":"pimp","english_translation_quality":"direct","notes":"Common and crude Dutch slang for pimp; etymology uncertain, possibly from 'pooien' (to pamper/flatter); considerably more stigmatizing and street-register than souteneur; widely used in journalism and everyday speech."}
