{"term":"bordeelhouder","lang":"nl","script":"latin","romanization":null,"category":"sex_work_pornography","subcategory":"brothel_owner","concept":"brothel_manager","is_novel_concept":false,"register":"slang_neutral","crude":30,"technical":15,"recognition_pct_current":85,"recognition_pct_peak":88,"peak_year":null,"regional":null,"definition":"A brothel owner or manager; a person who owns and operates a licensed sex establishment where sex workers sell services to clients.","english_term":"brothel owner","english_translation_quality":"direct","notes":"Transparent compound of bordeel (brothel) + houder (holder/keeper); gender-neutral in form but typically applied to men; used in legal and journalistic contexts; requires a municipal exploitation license in the Netherlands."}
